package com.kairos.backend.common;

/** Identifiers generated by the frontend, e.g. {@code workout-3f2c…} or {@code recovery-2026-10-13}. */
public final class ClientIds {

    public static final String PATTERN = "[A-Za-z0-9._:-]{1,80}";
    public static final String MESSAGE = "must be 1–80 letters, digits, '.', '_', ':' or '-'";

    private ClientIds() {
    }
}
